/**
 * Observed Open medians + percentile GRIDS — ground truth for the
 * score-scale acceptance protocol, v3 (grid pull 2026-11-04). Each row
 * carries the observed percentile curve at field percentiles 5..95
 * (step 5) with per-point finisher flags, so the harness can read ANY
 * conditional slice (above-wall grading for gated pieces), place a
 * prediction by inverse lookup, and never confuse finisher seconds
 * with rep counts. Quartile columns are derived from the grid (p25/50/
 * 75 points) for the v2 fallback path and the seed-validation rules.
 *
 * Pull (competition service; segment = 'general' ONLY — the view holds
 * eleven population segments per workout and pooling them interleaves
 * incompatible curves):
 *
 *   WITH oc AS (SELECT * FROM pe.workout_percentile_curve WHERE segment = 'general'),
 *   tp AS (SELECT unnest(ARRAY[5,10,...,95]) AS p),
 *   pts AS (SELECT oc.workout_id, tp.p,
 *       (array_agg(oc.score_value ORDER BY abs(oc.percentile - tp.p)))[1] AS score,
 *       (array_agg(oc.is_finisher ORDER BY abs(oc.percentile - tp.p)))[1] AS fin
 *     FROM oc CROSS JOIN tp GROUP BY oc.workout_id, tp.p)
 *   ... joined to pe.workout_features + crossfit.workouts_full (tier=rx, open).
 *
 * Known upstream data-quality notes carried forward from v2: the whole
 * 2017 season's time_domain_seconds is wrong for AMRAP/chipper rows
 * (SECONDS_UNTRUSTED below); 18.2 M's duration defaulted to the cap and
 * 24.1's sources disagree by ~a minute (DURATION_DISAGREES — the ranked
 * distribution wins, founder ruling); max-lift pieces are load-scored;
 * 23.3 is an extension AMRAP encoded as capped for-time. Upstream zeros
 * for "no cap"/"no fixed time domain" are seeded as null, not 0.
 */

export interface ObservedMedianRow {
  workout_name: string;
  gender: "M" | "F";
  year: number;
  /** observed median duration in seconds (cap-aware cohort statistic) */
  observed_median_s: number | null;
  time_cap_seconds: number | null;
  /** score-space quartiles (reps for rep-ranked fields, seconds for time) */
  p25_score: number | null;
  p50_score: number | null;
  p75_score: number | null;
  /** v3 fixture: the observed percentile curve as a ~19-point grid with
   *  per-point finisher flags — lets the harness read ANY conditional
   *  slice (above-wall grading for gated pieces, unit-aware comparisons)
   *  without re-pulling. Absent on v2 rows; the harness falls back to
   *  the quartile columns. */
  points?: Array<{ p: number; s: number; fin: boolean | null }>;
}

